export class ExperimentalMcpServerTasks{constructor(e){this._mcpServer=e}registerToolTask(e,t,r){const o={taskSupport:"required",...t.execution};if("forbidden"===o.taskSupport)throw new Error(`Cannot register task-based tool '${e}' with taskSupport 'forbidden'. Use registerTool() instead.`);return this._mcpServer._createRegisteredTool(e,t.title,t.description,t.inputSchema,t.outputSchema,t.annotations,o,t._meta,r)}}